            "CREATE TRIGGER character_cards_ad\nAFTER DELETE ON character_cards BEGIN\n  INSERT INTO character_cards_fts(character_cards_fts,rowid,\n                                  name,description,personality,scenario,system_prompt)\n  VALUES('delete',old.id,old.name,old.description,old.personality,old.scenario,old.system_prompt);\nEND",
            "CREATE TRIGGER character_cards_ai\nAFTER INSERT ON character_cards BEGIN\n  INSERT INTO character_cards_fts(rowid,name,description,personality,scenario,system_prompt)\n  SELECT new.id,new.name,new.description,new.personality,new.scenario,new.system_prompt\n  WHERE new.deleted = 0;\nEND",
            "CREATE TRIGGER character_cards_au\nAFTER UPDATE ON character_cards BEGIN\n  INSERT INTO character_cards_fts(character_cards_fts,rowid,\n                                  name,description,personality,scenario,system_prompt)\n  SELECT 'delete',old.id,old.name,old.description,old.personality,old.scenario,old.system_prompt\n  WHERE old.deleted = 0;\n\n  INSERT INTO character_cards_fts(rowid,name,description,personality,scenario,system_prompt)\n  SELECT new.id,new.name,new.description,new.personality,new.scenario,new.system_prompt\n  WHERE new.deleted = 0;\nEND",
            "CREATE TRIGGER character_cards_sync_create\nAFTER INSERT ON character_cards BEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('character_cards',CAST(NEW.id AS TEXT),'create',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'name',NEW.name,'description',NEW.description,'personality',NEW.personality,\n                     'scenario',NEW.scenario,'post_history_instructions',NEW.post_history_instructions,\n                     'first_message',NEW.first_message,'message_example',NEW.message_example,'creator_notes',NEW.creator_notes,\n                     'system_prompt',NEW.system_prompt,'alternate_greetings',NEW.alternate_greetings,'tags',NEW.tags,'creator',NEW.creator,\n                     'character_version',NEW.character_version,'extensions',NEW.extensions,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER character_cards_sync_delete\nAFTER UPDATE ON character_cards\nWHEN OLD.deleted = 0 AND NEW.deleted = 1\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('character_cards',CAST(NEW.id AS TEXT),'delete',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'deleted',NEW.deleted,'last_modified',NEW.last_modified,\n                     'version',NEW.version,'client_id',NEW.client_id));\nEND",
            "CREATE TRIGGER character_cards_sync_undelete\nAFTER UPDATE ON character_cards\nWHEN OLD.deleted = 1 AND NEW.deleted = 0\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('character_cards',CAST(NEW.id AS TEXT),'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'name',NEW.name,'description',NEW.description,'personality',NEW.personality,\n                     'scenario',NEW.scenario,'post_history_instructions',NEW.post_history_instructions,\n                     'first_message',NEW.first_message,'message_example',NEW.message_example,'creator_notes',NEW.creator_notes,\n                     'system_prompt',NEW.system_prompt,'alternate_greetings',NEW.alternate_greetings,'tags',NEW.tags,'creator',NEW.creator,\n                     'character_version',NEW.character_version,'extensions',NEW.extensions,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER character_cards_sync_update\nAFTER UPDATE ON character_cards\nWHEN OLD.deleted = NEW.deleted AND (\n     OLD.name IS NOT NEW.name OR\n     OLD.description IS NOT NEW.description OR\n     OLD.personality IS NOT NEW.personality OR\n     OLD.scenario IS NOT NEW.scenario OR\n     OLD.image IS NOT NEW.image OR\n     OLD.post_history_instructions IS NOT NEW.post_history_instructions OR\n     OLD.first_message IS NOT NEW.first_message OR\n     OLD.message_example IS NOT NEW.message_example OR\n     OLD.creator_notes IS NOT NEW.creator_notes OR\n     OLD.system_prompt IS NOT NEW.system_prompt OR\n     OLD.alternate_greetings IS NOT NEW.alternate_greetings OR\n     OLD.tags IS NOT NEW.tags OR\n     OLD.creator IS NOT NEW.creator OR\n     OLD.character_version IS NOT NEW.character_version OR\n     OLD.extensions IS NOT NEW.extensions OR\n     OLD.last_modified IS NOT NEW.last_modified OR\n     OLD.version IS NOT NEW.version)\nBEGIN\n  INSERT INTO sync_log(entity,entity_id,operation,timestamp,client_id,version,payload)\n  VALUES('character_cards',CAST(NEW.id AS TEXT),'update',NEW.last_modified,NEW.client_id,NEW.version,\n         json_object('id',NEW.id,'name',NEW.name,'description',NEW.description,'personality',NEW.personality,\n                     'scenario',NEW.scenario,'post_history_instructions',NEW.post_history_instructions,\n                     'first_message',NEW.first_message,'message_example',NEW.message_example,'creator_notes',NEW.creator_notes,\n                     'system_prompt',NEW.system_prompt,'alternate_greetings',NEW.alternate_greetings,'tags',NEW.tags,'creator',NEW.creator,\n                     'character_version',NEW.character_version,'extensions',NEW.extensions,'created_at',NEW.created_at,\n                     'last_modified',NEW.last_modified,'deleted',NEW.deleted,'client_id',NEW.client_id,'version',NEW.version));\nEND",
            "CREATE TRIGGER chat_dictionaries_ad\nAFTER DELETE ON chat_dictionaries BEGIN\n  DELETE FROM chat_dictionaries_fts WHERE rowid = OLD.id;\nEND",
            "CREATE TRIGGER chat_dictionaries_ai\nAFTER INSERT ON chat_dictionaries BEGIN\n  INSERT INTO chat_dictionaries_fts(rowid, name, description, content)\n  VALUES(NEW.id, NEW.name, NEW.description, NEW.content);\nEND",
            "CREATE TRIGGER chat_dictionaries_au\nAFTER UPDATE ON chat_dictionaries BEGIN\n  INSERT INTO chat_dictionaries_fts(chat_dictionaries_fts, rowid, name, description, content)\n  SELECT 'delete', OLD.id, OLD.name, OLD.description, OLD.content\n  WHERE OLD.deleted = 0;\n\n  INSERT INTO chat_dictionaries_fts(rowid, name, description, content)\n  SELECT NEW.id, NEW.name, NEW.description, NEW.content\n  WHERE NEW.deleted = 0;\nEND",
            "CREATE TRIGGER chat_dictionaries_sync_create\nAFTER INSERT ON chat_dictionaries BEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('chat_dictionaries', CAST(NEW.id AS TEXT), 'create', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'name', NEW.name, 'description', NEW.description,\n                     'file_path', NEW.file_path, 'strategy', NEW.strategy, 'max_tokens', NEW.max_tokens,\n                     'enabled', NEW.enabled, 'created_at', NEW.created_at, 'last_modified', NEW.last_modified,\n                     'deleted', NEW.deleted, 'client_id', NEW.client_id, 'version', NEW.version));\nEND",
            "CREATE TRIGGER chat_dictionaries_sync_delete\nAFTER UPDATE ON chat_dictionaries\nWHEN OLD.deleted = 0 AND NEW.deleted = 1\nBEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('chat_dictionaries', CAST(NEW.id AS TEXT), 'delete', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'deleted', NEW.deleted, 'last_modified', NEW.last_modified,\n                     'version', NEW.version, 'client_id', NEW.client_id));\nEND",
            "CREATE TRIGGER chat_dictionaries_sync_undelete\nAFTER UPDATE ON chat_dictionaries\nWHEN OLD.deleted = 1 AND NEW.deleted = 0\nBEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('chat_dictionaries', CAST(NEW.id AS TEXT), 'update', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'name', NEW.name, 'description', NEW.description,\n                     'file_path', NEW.file_path, 'strategy', NEW.strategy, 'max_tokens', NEW.max_tokens,\n                     'enabled', NEW.enabled, 'created_at', NEW.created_at, 'last_modified', NEW.last_modified,\n                     'deleted', NEW.deleted, 'client_id', NEW.client_id, 'version', NEW.version));\nEND",
            "CREATE TRIGGER chat_dictionaries_sync_update\nAFTER UPDATE ON chat_dictionaries\nWHEN OLD.deleted = NEW.deleted AND (\n     OLD.name IS NOT NEW.name OR\n     OLD.description IS NOT NEW.description OR\n     OLD.file_path IS NOT NEW.file_path OR\n     OLD.content IS NOT NEW.content OR\n     OLD.entries_json IS NOT NEW.entries_json OR\n     OLD.strategy IS NOT NEW.strategy OR\n     OLD.max_tokens IS NOT NEW.max_tokens OR\n     OLD.enabled IS NOT NEW.enabled OR\n     OLD.last_modified IS NOT NEW.last_modified OR\n     OLD.version IS NOT NEW.version)\nBEGIN\n  INSERT INTO sync_log(entity, entity_id, operation, timestamp, client_id, version, payload)\n  VALUES('chat_dictionaries', CAST(NEW.id AS TEXT), 'update', NEW.last_modified, NEW.client_id, NEW.version,\n         json_object('id', NEW.id, 'name', NEW.name, 'description', NEW.description,\n                     'file_path', NEW.file_path, 'strategy', NEW.strategy, 'max_tokens', NEW.max_tokens,\n                     'enabled', NEW.enabled, 'created_at', NEW.created_at, 'last_modified', NEW.last_modified,\n                     'deleted', NEW.deleted, 'client_id', NEW.client_id, 'version', NEW.version));\nEND",
            "CREATE TRIGGER chat_dictionaries_update_timestamp\nAFTER UPDATE ON chat_dictionaries\nBEGIN\n  UPDATE chat_dictionaries SET last_modified = CURRENT_TIMESTAMP WHERE id = NEW.id;\nEND",
            "CREATE TRIGGER conversation_dictionary_index_ad\nAFTER DELETE ON conversations BEGIN\n  DELETE FROM conversation_dictionary_attachments WHERE conversation_id = OLD.id;\n  DELETE FROM conversation_dictionary_unresolved  WHERE conversation_id = OLD.id;\nEND",
            "CREATE TRIGGER conversation_dictionary_index_ai\nAFTER INSERT ON conversations\nWHEN NEW.metadata LIKE '%active_dictionaries%'\nBEGIN\n  INSERT OR IGNORE INTO conversation_dictionary_attachments(conversation_id, dictionary_id)\n  SELECT NEW.id, CAST(element.value AS INTEGER)\n    FROM json_each(\n           CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n           '$.active_dictionaries'\n         ) AS element\n   WHERE json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END) = 'object'\n     AND json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                   '$.active_dictionaries') = 'array'\n     AND element.type = 'integer'\n     AND typeof(element.value) = 'integer';\n\n  INSERT OR IGNORE INTO conversation_dictionary_unresolved(conversation_id)\n  SELECT NEW.id\n   WHERE json_valid(NEW.metadata) = 0\n      OR (length(NEW.metadata) - length(replace(NEW.metadata, 'active_dictionaries', ''))) / 19 <> 1\n      OR EXISTS (\n           SELECT 1\n             FROM json_each(\n                    CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                    '$.active_dictionaries'\n                  ) AS element\n            WHERE json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                            '$.active_dictionaries') = 'array'\n              AND element.type NOT IN ('null', 'object', 'array')\n              AND NOT (element.type = 'integer' AND typeof(element.value) = 'integer')\n         );\nEND",
            "CREATE TRIGGER conversation_dictionary_index_au\nAFTER UPDATE ON conversations\nWHEN NEW.metadata IS NOT OLD.metadata OR NEW.id <> OLD.id\nBEGIN\n  DELETE FROM conversation_dictionary_attachments\n   WHERE conversation_id IN (OLD.id, NEW.id);\n  DELETE FROM conversation_dictionary_unresolved\n   WHERE conversation_id IN (OLD.id, NEW.id);\n\n  INSERT OR IGNORE INTO conversation_dictionary_attachments(conversation_id, dictionary_id)\n  SELECT NEW.id, CAST(element.value AS INTEGER)\n    FROM json_each(\n           CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n           '$.active_dictionaries'\n         ) AS element\n   WHERE NEW.metadata LIKE '%active_dictionaries%'\n     AND json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END) = 'object'\n     AND json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                   '$.active_dictionaries') = 'array'\n     AND element.type = 'integer'\n     AND typeof(element.value) = 'integer';\n\n  INSERT OR IGNORE INTO conversation_dictionary_unresolved(conversation_id)\n  SELECT NEW.id\n   WHERE NEW.metadata LIKE '%active_dictionaries%'\n     AND (json_valid(NEW.metadata) = 0\n      OR (length(NEW.metadata) - length(replace(NEW.metadata, 'active_dictionaries', ''))) / 19 <> 1\n      OR EXISTS (\n           SELECT 1\n             FROM json_each(\n                    CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                    '$.active_dictionaries'\n                  ) AS element\n            WHERE json_type(CASE WHEN json_valid(NEW.metadata) THEN NEW.metadata ELSE '{}' END,\n                            '$.active_dictionaries') = 'array'\n              AND element.type NOT IN ('null', 'object', 'array')\n              AND NOT (element.type = 'integer' AND typeof(element.value) = 'integer')\n         ));\nEND",
            "CREATE TRIGGER conversations_ad\nAFTER DELETE ON conversations BEGIN\n  INSERT INTO conversations_fts(conversations_fts,rowid,title)\n  SELECT 'delete',old.rowid,old.title\n  WHERE old.title IS NOT NULL;\nEND",
            "CREATE TRIGGER conversations_ai\nAFTER INSERT ON conversations BEGIN\n  INSERT INTO conversations_fts(rowid,title)\n  SELECT new.rowid,new.title\n  WHERE new.deleted = 0 AND new.title IS NOT NULL;\nEND",
            "CREATE TRIGGER conversations_au\nAFTER UPDATE ON conversations BEGIN\n  INSERT INTO conversations_fts(conversations_fts,rowid,title)\n  SELECT 'delete',old.rowid,old.title\n  WHERE old.deleted = 0 AND old.title IS NOT NULL;\n\n  INSERT INTO conversations_fts(rowid,title)\n  SELECT new.rowid,new.title\n  WHERE new.deleted = 0 AND new.title IS NOT NULL;\nEND",
